import type { CommandSpec, EngineInterface, On } from "claude-code";

import { limitPrompt, limitStep } from "./limit-guard";
import {
  agentKind,
  commandKind,
  DEFAULT_MODE,
  displayName,
  type Effort,
  escalation,
  isMode,
  type Kind,
  kindOfLabel,
  LABELS,
  type Mode,
  pick,
  profileName,
  PROFILES,
} from "./model-policy";
import {
  askFirstModel,
  dropSwitch,
  effortLock,
  override,
  reset,
  restoreSwitch,
  running,
  switchTo,
} from "./model-switch";
import { noteAgent } from "./chat-facts";
import { isOrchestrating, orchestrateNote } from "./orchestrate";

// Picks model and effort before the model runs (it cannot change its own turn's effort):
// - the first prompt of a chat (a new session or after /clear) picks a model from the profile,
//   before the prompt is sent; when it differs from the session's, the user is asked to
//   switch or stay, and a switch rewrites every main request;
// - every prompt picks the effort; a later prompt that needs a stronger model than the one
//   running escalates (model-policy.ts `escalation`): one tier short it runs at the top effort,
//   further short the user picks: switch now (light context only), compact or clear and then
//   switch and send it again, or stay at the top effort (not asked again this chat);
// - a subagent the engine defines gets its own model and effort for its task.
// The profile (lean, balanced, quality, or off) is kept in $.store across sessions, a switch
// per session id, so a mod reload or restart keeps it.

export const modeCommand: CommandSpec = {
  name: "mode",
  description:
    "Pick kit's model/effort profile: lean, balanced, quality or off",
  argumentHint: "[lean|balanced|quality|off]",
  immediate: true,
};

const STORE_KEY = "mode";
const CLASSIFY_CHARS = 4000;

let mode: Mode | undefined; // read from $.store on first use
let decided = false; // the session's model question was settled
let stayed = false; // the user chose to stay on a weaker model: no more asking this chat
let effort: Effort | undefined; // the effort for the current prompt's requests
const agentEffort = new Map<string, Effort>(); // subagent id → its effort

export async function getMode($: EngineInterface): Promise<Mode> {
  if (mode === undefined) {
    const stored = await $.store.get(STORE_KEY).catch(() => undefined);
    mode = isMode(stored) ? stored : DEFAULT_MODE;
  }
  return mode;
}

export async function setMode($: EngineInterface, next: Mode) {
  mode = next;
  await $.store.set(STORE_KEY, next).catch(() => {});
  if (next === "off") {
    dropSwitch(false);
    effort = undefined;
  }
  await showStatus($);
  $.ui.invalidate("ui.render");
}

async function kindOf(
  $: EngineInterface,
  text: string,
): Promise<Kind | undefined> {
  const known = commandKind(text);
  if (known) return known;
  const label = await $.model
    .classify(text.slice(0, CLASSIFY_CHARS), Object.values(LABELS), {
      model: "haiku",
    })
    .catch(() => undefined);
  return kindOfLabel(label);
}

// What the band shows: the model main requests really go to (the picker keeps the
// session's), and the effort they run at, `locked` when set from the band.
export async function runState($: EngineInterface) {
  const locked = await effortLock($);
  const off = (await getMode($)) === "off";
  return {
    model: await running($),
    effort: locked ?? (off ? undefined : effort),
    locked: !!locked,
  };
}

// The band's model switch: keep the context, or compact or clear it first.
export async function switchModel(
  $: EngineInterface,
  model: string,
  way: "keep" | "compact" | "clear",
) {
  if (way !== "keep" && !(await reset($, way))) return;
  decided = true; // picked by hand: a new chat asks nothing about it
  await switchTo($, model);
  await showStatus($);
}

async function showStatus($: EngineInterface) {
  $.ui.invalidate("ui.render");
}

type Way = "now" | "compact" | "clear" | "stay";

// A later prompt that needs `want`, above the model running. One tier short, or after the user
// chose to stay, it runs at the top effort; further short the user picks how to go on. Returns
// why the prompt is held when a clear or compact runs first and sends it again.
async function escalate(
  $: EngineInterface,
  text: string,
  want: string,
  mayAsk: boolean,
): Promise<string | undefined> {
  const have = await running($);
  const usage = await $.session.usage().catch(() => undefined);
  const step = escalation(have, want, usage?.context?.percent);
  if (step.step === "none") return undefined;
  if (step.step === "effort" || stayed || !mayAsk) {
    effort = "max";
    return undefined;
  }
  const to = displayName(step.want);
  const from = displayName(have);
  const ways = new Map<string, Way>();
  if (step.switchNow) ways.set(`Switch to ${to} now`, "now");
  ways.set(`Compact, then ${to}`, "compact");
  ways.set(`Clear, then ${to}`, "clear");
  ways.set(`Stay on ${from} at max effort`, "stay");
  const answer = await $.ui
    .ask(`This prompt needs ${to}; ${from} is running. How to go on?`, {
      header: "Model",
      options: [...ways.keys()],
    })
    .catch(() => undefined);
  const way = (answer !== undefined && ways.get(answer)) || "stay";
  if (way === "now") {
    await switchTo($, step.want);
    return undefined;
  }
  if (way === "stay") {
    stayed = true;
    effort = "max";
    return undefined;
  }
  const level = effort;
  // Outside the hook: a clear or compact rejects inside the hook the prompt waits on.
  $.clock.after(300, () => resend($, way, step.want, text, level));
  return `kit: ${way === "clear" ? "clearing" : "compacting"}, then ${to} runs your prompt`;
}

// Clears or compacts, switches to `want` and sends the held prompt again. On a failure the
// prompt goes back into the input box, so nothing typed is lost.
async function resend(
  $: EngineInterface,
  way: "compact" | "clear",
  want: string,
  text: string,
  level: Effort | undefined,
) {
  if (!(await reset($, way))) {
    await $.prompt.fill({ text }).catch(() => {}); // the prompt is back in the input box
    return;
  }
  decided = true;
  await switchTo($, want);
  effort = level;
  await showStatus($);
  await $.prompt.submit({ text, asUser: true }).catch(async (err) => {
    $.ui.toast(`kit: could not send your prompt (${String(err)})`);
    await $.prompt.fill({ text }).catch(() => {});
  });
}

export function autoModel(on: On) {
  // A new chat (startup or /clear) asks again; a resume keeps the model it ran on.
  on(
    "classic.SessionStart",
    { source: /^(startup|clear)$/ },
    async ($, e, next) => {
      const started = await next(e);
      if (e.agent_type) return started;
      decided = false;
      stayed = false;
      dropSwitch(true); // a new chat: nothing stored to pick up
      effort = undefined;
      agentEffort.clear();
      await showStatus($);
      return started;
    },
  );

  on("prompt.submit", async ($, e, next) => {
    const held = await limitPrompt($, e.text);
    if (held) {
      $.ui.toast(held, { timeoutMs: 10_000 });
      return { drop: held };
    }
    const now = await getMode($);
    const typed = e.origin.kind === "composer" || e.origin.kind === "bridge";
    const orchestrating = typed && (await isOrchestrating($));
    if (!typed || (now === "off" && !orchestrating)) return next(e);
    const kind = (await kindOf($, e.text)) ?? "routine";
    if (now !== "off") {
      const p = pick(now, kind);
      if (await restoreSwitch($)) decided = true; // a reload kept the switch
      let asked = false;
      if (!decided) {
        decided = true;
        // An orchestrator keeps its model: handing work off is what makes it cheaper.
        asked = !orchestrating && (await askFirstModel($, p.model));
      }
      effort = p.effort;
      // The first prompt's question just settled the model: no second one for it.
      const parked = await escalate($, e.text, p.model, !asked);
      await showStatus($);
      if (parked) {
        $.ui.toast(parked, { timeoutMs: 10_000 });
        return { drop: parked };
      }
    }
    // Orchestrate (the band's ⑂): a note for this kind of work rides along with the prompt.
    const note = orchestrating ? orchestrateNote(kind) : undefined;
    return next(note ? { ...e, context: [...(e.context ?? []), note] } : e);
  });

  // A streaming event: the hook is a generator that forwards the chunks beneath.
  on("turn.step", async function* ($, e, next) {
    const stopped = await limitStep($, e); // the plan limit is nearly used up
    if (stopped) return stopped;
    let step = e;
    const isOn = (await getMode($)) !== "off";
    if (e.agentId) {
      const own = agentEffort.get(e.agentId);
      if (isOn && own && e.effort !== undefined) step = { ...e, effort: own };
    } else {
      // An effort locked from the band holds even with the profile off.
      const model = isOn ? ((await override($)) ?? e.model) : e.model;
      const want = (await effortLock($)) ?? (isOn ? effort : undefined);
      const level = want && e.effort !== undefined ? want : e.effort;
      step = { ...e, model, effort: level };
    }
    return yield* next(step);
  });

  on("agent.spawn", async ($, e, next) => {
    noteAgent(e.subagentType);
    const now = await getMode($);
    if (now === "off" || e.fork) return next(e);
    const isEngine = e.provider.plugin === "engine";
    const known = agentKind(e.subagentType);
    // A plugin's or user's agent keeps its own definition unless kit knows its work.
    if (!isEngine && !known) return next(e);
    const kind = known ?? (await kindOf($, e.prompt)) ?? "routine";
    const p = pick(now, kind);
    const spawned = await next(
      isEngine && !e.model ? { ...e, model: p.model } : e,
    );
    if (spawned.agentId) agentEffort.set(spawned.agentId, p.effort);
    return spawned;
  });

  on("command.run", { command: "mode" }, async ($, e) => {
    const arg = e.args.trim().toLowerCase();
    if (isMode(arg)) {
      await setMode($, arg);
      return { text: `kit profile: ${profileName(arg)}.` };
    }
    const now = await getMode($);
    return {
      text: `kit profile: ${profileName(now)}. Pick one: /mode ${[...PROFILES, "off"].join("|")}`,
    };
  });
}

files.hooks/fresh-start.ts:
import type { On, ToolSpec } from "claude-code";

// /build's safe point, automated: the model calls fresh_start after the user picked
// "Fresh start"; when that turn ends, the chat clears and /kit:build <slug> resumes from the
// spec in the fresh one. Same chain as the roadmap pane's Pick up, but run from turn.complete.

const TOOL = "mcp__kit__fresh_start";
const SLUG = /^[a-z0-9][a-z0-9-]*$/;

let armed: string | null = null;

export const freshTool: ToolSpec = {
  name: "fresh_start",
  description:
    "kit /build safe point: after this turn ends, clear the chat and run /kit:build <slug> " +
    "in the fresh one. Call it only after the user chose Fresh start, then end the turn.",
  inputSchema: {
    type: "object",
    properties: { slug: { type: "string" } },
    required: ["slug"],
  },
};

export function freshStart(on: On) {
  on("tool.check", { tool: TOOL }, () => ({ decision: "allow" }));

  on("tool.call", { tool: TOOL }, async (_$, e) => {
    const slug = String((e as unknown as { slug?: unknown }).slug ?? "");
    if (!SLUG.test(slug))
      return { result: `Not armed: invalid slug "${slug}".` };
    armed = slug;
    return {
      result: `Armed: when this turn ends, the chat clears and /kit:build ${slug} starts. End the turn now.`,
    };
  });

  on("turn.complete", async ($, e, next) => {
    const done = await next(e);
    if (!armed || e.agentId) return done;
    const slug = armed;
    armed = null;
    if (e.reason !== "answer") {
      $.ui.toast(`kit: fresh start for ${slug} cancelled`);
      return done;
    }
    // Outside the hook: $.command.run rejects inside a hook the turn waits on.
    $.clock.after(300, async () => {
      try {
        await $.command.run({ command: "clear" });
      } catch (err) {
        // Building on in this same chat would defeat the point: leave it to the user.
        $.ui.toast(
          `kit: could not clear (${String(err)}). Run /clear, then /build ${slug}`,
        );
        return;
      }
      await $.command
        .run({ command: "kit:build", args: slug })
        .catch((err) =>
          $.ui.toast(`kit: could not start /build ${slug}: ${String(err)}`),
        );
    });
    return done;
  });
}

files.hooks/chat-facts.ts:
import type { EngineInterface } from "claude-code";

import { runState } from "./auto-model";
import type { Chat, Excerpt } from "./roadmap-parts";

// What the roadmap pane's Chat tab shows. register.tsx and auto-model.ts note what this chat
// touched (files written or edited, subagents, compactions) as it happens, so it counts from
// when the mod loaded; a /clear starts over.

const files = new Set<string>();
const agents = new Map<string, number>();
let compactions = 0;

export function noteFile(path: string) {
  files.add(path.replace(/\\/g, "/"));
}

export function noteAgent(type: string) {
  agents.set(type, (agents.get(type) ?? 0) + 1);
}

export function noteCompact() {
  compactions += 1;
}

export function resetChat() {
  files.clear();
  agents.clear();
  compactions = 0;
}

// The run, the session's usage (the context by category, as /context estimates it) and
// what this chat touched, paths relative to the project.
export async function readChat($: EngineInterface): Promise<Chat> {
  const run = await runState($);
  const usage = await $.session
    .usage({ breakdown: "summary" })
    .catch(() => undefined);
  const b = usage?.context.breakdown;
  const root = (await $.session.root().catch(() => "")).replace(/\\/g, "/");
  const now = await $.clock.now();
  return {
    model: run.model,
    effort: run.effort,
    locked: run.locked,
    turns: await $.session.turns().catch(() => 0),
    minutes: usage
      ? Math.max(0, Math.round((now - usage.startedAt) / 60000))
      : 0,
    usd: usage?.cost?.usd,
    context: (b?.categories ?? [])
      .filter((c) => !c.isDeferred && c.tokens > 0 && !/free/i.test(c.name))
      .map((c) => ({ name: c.name, tokens: c.tokens })),
    used: b?.totalTokens ?? usage?.context.tokens ?? 0,
    max: b?.maxTokens ?? usage?.context.window ?? 0,
    files: [...files].map((f) =>
      root && f.startsWith(`${root}/`) ? f.slice(root.length + 1) : f,
    ),
    agents: [...agents].map(([type, n]) => ({ type, n })),
    compactions,
  };
}

// The Messages tab: this chat's latest messages with text, newest first, on one line each.
// Injected context (a text that opens with a tag) is left out.
export async function readMessages($: EngineInterface): Promise<Excerpt[]> {
  const messages = await $.session.messages().catch(() => []);
  return messages
    .map((m) => ({
      role: m.role === "user" ? ("you" as const) : ("claude" as const),
      text: m.text.replace(/\s+/g, " ").trim(),
    }))
    .filter((m) => m.text && !m.text.startsWith("<"))
    .slice(-12)
    .reverse();
}

let remembered = 0; // when Remember was last pressed: a press within 2s is a double click

// Remember: sent as the person's own prompt (they pressed it), just after the press; the
// kit:lessons skill decides whether it qualifies and where it goes.
export async function remember($: EngineInterface, text: string) {
  const now = await $.clock.now();
  if (now - remembered < 2000) return;
  remembered = now;
  const prompt =
    "Remember this as a project lesson through the kit:lessons skill, only if it qualifies " +
    `there:\n\n> ${text.slice(0, 1200)}`;
  $.clock.after(50, async () => {
    await $.prompt
      .submit({ text: prompt, asUser: true })
      .catch((err) => $.ui.toast(`kit: could not send it (${String(err)})`));
  });
}

files.hooks/kit-band.tsx:
import type { CommandSpec, EngineInterface, On } from "claude-code";

import { getMode, runState, setMode, switchModel } from "./auto-model";
import { GIT_ITEMS, gitAction } from "./git-menu";
import { isWarm, setWarm, warmCommandRun, warmInfo } from "./keep-warm";
import { limitInfo, resumeNow } from "./limit-guard";
import {
  displayName,
  EFFORTS,
  family,
  MODELS,
  type Mode,
  PROFILES,
  profileName,
} from "./model-policy";
import { reset, setEffortLock } from "./model-switch";
import { isOrchestrating, setOrchestrating } from "./orchestrate";
import { openRoadmap } from "./roadmap-open";
import type { Usage } from "./roadmap-parts";
import { PANE } from "./roadmap-view";

// The band above the prompt, top to bottom: an open menu (a bordered block), then context and
// plan usage (register.tsx measures it after each turn) with what acts on the chat at its right:
// compact (⇲) and clear (⌫), run at once. Below, in three groups:
// the model main requests go to and its effort (▪ when locked), each opening only its own
// menu (the profile from auto-model.ts; the models, then keep the context,
// compact or clear; the effort's the levels, a pick locks it, Auto unlocks); /commit (✓) with a Git menu (⎇, git-menu.ts) and the dashboard pane (▤);
// orchestrate (⑂, orchestrate.ts) with keep cache (♨, keep-warm.ts). The plan-limit pause with
// Resume now (limit-guard.ts) follows on its own line. Each icon carries a short word.
// It yields to a survey. /band draws it again; /warm toggles keep warm.

export const bandCommand: CommandSpec = {
  name: "band",
  description:
    "Show kit's band above the prompt (profile, model, effort, compact, clear, roadmap)",
  immediate: true,
};

type Menu = "profile" | "model" | "effort" | "git" | "way";

let menu: Menu | null = null; // the unfolded menu row
let usage: Usage[] = []; // context and plan limits, from register.tsx

// Context and plan limits, as register.tsx measures them after each turn.
export function bandUsage(figures: Usage[]): void {
  usage = figures;
}

let target = ""; // the model picked in the model row, for the way row

// Compact, clear and a switch run just after the press: inside it they can be refused.
function soon($: EngineInterface, work: () => Promise<unknown>) {
  $.clock.after(50, async () => {
    await work();
    $.ui.invalidate("ui.render");
  });
}

function unfold($: EngineInterface, next: Menu | null) {
  menu = menu === next ? null : next;
  $.ui.invalidate("ui.render");
}

export function kitBand(on: On) {
  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e);
    const { Box, Button, Text } = $.ui.resolve(e);
    const panes = await $.ui.panes().catch(() => []);
    const isOpen = panes.some((p) => p.id === PANE && p.isPlaced);
    const now = await getMode($);
    const run = await runState($);
    const pause = await limitInfo($);
    const warm = isWarm();
    const orch = await isOrchestrating($);
    const warmed = warmInfo();
    const done = () => unfold($, null);
    const close = (
      <Button key="kit-menu-close" label="×" dimColor onPress={done} />
    );

    // A line of the run menu: its name in a narrow column, its choices beside it.
    const line = (name: string, items: unknown[]) => (
      <Box key={`kit-line-${name}`} gap={1}>
        <Box width={8} flexShrink={0}>
          <Text dimColor>{name}</Text>
        </Box>
        <Box gap={1} flexWrap="wrap">
          {items as never}
        </Box>
      </Box>
    );

    let body = null;
    if (menu === "profile") {
      const modes: Mode[] = [...PROFILES, "off"];
      body = (
        <Box flexDirection="column" flexGrow={1}>
          {line(
            "Profile",
            modes.map((m) => (
              <Button
                key={`kit-mode-${m}`}
                label={profileName(m)}
                dimColor={now !== m}
                onPress={() => {
                  void setMode($, m).then(done);
                }}
              />
            )),
          )}
        </Box>
      );
    } else if (menu === "model") {
      body = (
        <Box flexDirection="column" flexGrow={1}>
          {line(
            "Model",
            MODELS.map((m) => (
              <Button
                key={`kit-model-${m}`}
                label={displayName(m)}
                dimColor={family(m) !== family(run.model)}
                onPress={() => {
                  if (family(m) === family(run.model)) return done();
                  target = m;
                  unfold($, "way");
                }}
              />
            )),
          )}
        </Box>
      );
    } else if (menu === "git") {
      body = (
        <Box flexDirection="column" flexGrow={1}>
          {line(
            "Git",
            GIT_ITEMS.map((g) => (
              <Button
                key={`kit-git-${g}`}
                label={g}
                onPress={() => {
                  done();
                  void gitAction($, g);
                }}
              />
            )),
          )}
        </Box>
      );
    } else if (menu === "effort") {
      const levels = ["auto", ...EFFORTS] as const;
      body = (
        <Box flexDirection="column" flexGrow={1}>
          {line(
            "Effort",
            levels.map((l) => (
              <Button
                key={`kit-effort-${l}`}
                label={l === "auto" ? "Auto" : l}
                dimColor={run.locked ? run.effort !== l : l !== "auto"}
                onPress={() => {
                  void setEffortLock($, l === "auto" ? undefined : l).then(done);
                }}
              />
            )),
          )}
        </Box>
      );
    } else if (menu === "way") {
      const ways = [
        ["keep", "Keep context"],
        ["compact", "Compact"],
        ["clear", "Clear"],
      ] as const;
      body = (
        <Box gap={1} flexWrap="wrap" flexGrow={1}>
          <Text dimColor>{`→ ${displayName(target)}:`}</Text>
          {ways.map(([way, label]) => (
            <Button
              key={`kit-way-${way}`}
              label={label}
              onPress={() => {
                done();
                soon($, () => switchModel($, target, way));
              }}
            />
          ))}
        </Box>
      );
    }

    return (
      <Box flexDirection="column">
        {body ? (
          <Box
            key="kit-menu"
            gap={1}
            borderStyle="round"
            borderColor="#334155"
            paddingX={1}
            marginBottom={1}
          >
            {body}
            {close}
          </Box>
        ) : null}
        <Box justifyContent="space-between" gap={2} flexWrap="wrap" marginBottom={1}>
          <Box key="kit-usage" gap={3} flexWrap="wrap">
            {usage.map((u) => (
              <Text key={`kit-usage-${u.label}`}>
                <Text dimColor>{`${u.label} `}</Text>
                <Text bold>
                  {u.value}
                </Text>
                {u.note ? <Text dimColor>{` · ${u.note}`}</Text> : null}
              </Text>
            ))}
          </Box>
          <Box gap={1} flexWrap="wrap">
            <Button
              key="kit-compact"
              label="⇲ Compact"
              onPress={() => soon($, () => reset($, "compact"))}
            />
            <Button
              key="kit-clear"
              label="⌫ Clear"
              onPress={() => soon($, () => reset($, "clear"))}
            />
          </Box>
        </Box>
        <Box justifyContent="space-between" gap={1} flexWrap="wrap">
          <Box key="kit-group-model" gap={1}>
            <Button
              key="kit-model"
              label={displayName(run.model)}
              onPress={() => unfold($, "model")}
            />
            <Button
              key="kit-profile"
              label={profileName(now)}
              onPress={() => unfold($, "profile")}
            />
            <Button
              key="kit-effort"
              label={`${run.effort ?? "auto"}${run.locked ? " ▪" : ""}`}
              onPress={() => unfold($, "effort")}
            />
          </Box>
          <Box key="kit-group-project" gap={1}>
            <Button
              key="kit-commit"
              label="✓ Commit"
              onPress={() => {
                void $.command
                  .run({ command: "kit:commit" })
                  .catch((err) =>
                    $.ui.toast(`kit: could not start /commit: ${String(err)}`),
                  );
              }}
            />
            <Button
              key="kit-git"
              label="⎇ Git"
              onPress={() => unfold($, "git")}
            />
            <Button
              key="kit-roadmap"
              label={isOpen ? "▤ Close dashboard" : "▤ Dashboard"}
              onPress={() => {
                const toggle = isOpen ? $.ui.close({ id: PANE }) : openRoadmap($);
                void toggle.then(() => $.ui.invalidate("ui.render"));
              }}
            />
          </Box>
          <Box key="kit-group-keep" gap={1}>
            <Button
              key="kit-orchestrate"
              label="⑂ Orchestrate"
              dimColor={!orch}
              onPress={() => {
                void setOrchestrating($, !orch).then(() =>
                  $.ui.invalidate("ui.render"),
                );
              }}
            />
            <Button
              key="kit-warm"
              label="♨ Keep cache"
              dimColor={!warm}
              onPress={() => {
                void setWarm($, !warm);
              }}
            />
          </Box>
        </Box>
        {warmed || pause ? (
          <Box gap={1} flexWrap="wrap">
            {warmed ? <Text dimColor>{warmed}</Text> : null}
            {pause ? <Text color="#f59e0b">{pause}</Text> : null}
            {pause ? (
              <Button
                key="kit-resume"
                label="Resume now"
                onPress={() => {
                  void resumeNow($);
                }}
              />
            ) : null}
          </Box>
        ) : null}
      </Box>
    );
  });

  on("command.run", { command: "warm" }, async ($, e) => ({
    text: await warmCommandRun($, e.args),
  }));

  // There is no call that unfolds a band the person folded; a redraw is what a plugin has.
  on("command.run", { command: "band" }, async ($) => {
    $.ui.invalidate("ui.render");
    return {
      text: "kit band drawn above the prompt. Folded ([+])? ctrl+x ctrl+a unfolds it.",
    };
  });
}

