import type { Parts, Tab } from "./roadmap-parts";

// The dashboard pane's tabs (no tab element exists: a row of buttons, the shown one at full
// strength), and the Session and Messages tabs. Pure, like roadmap-parts.tsx.

const TABS: [Tab, string][] = [
  ["roadmap", "▤ Roadmap"],
  ["messages", "◈ Messages"],
  ["chat", "◎ Session"],
];

export function tabRow(p: Parts) {
  const { Box, Button } = p.el;
  return (
    <Box gap={1} flexWrap="wrap">
      {TABS.map(([t, label]) => (
        <Button
          key={`tab-${t}`}
          label={label}
          dimColor={p.tab !== t}
          onPress={() => p.act.tab(t)}
        />
      ))}
    </Box>
  );
}

// The context bar's colors, one per category in order; the rest of the window stays dim.
const SHADES = [
  "#818cf8",
  "#22c55e",
  "#f59e0b",
  "#38bdf8",
  "#f472b6",
  "#a3e635",
];
const BAR = 32;
const k = (tokens: number) => `${Math.round(tokens / 1000)}k`;

function duration(min: number): string {
  const h = Math.floor(min / 60);
  return h ? `${h}h ${min % 60}m` : `${min}m`;
}

// The Session tab (id "chat"): the run, the context by category as a bar, what this chat touched.
export function chatTab(p: Parts) {
  const { Box, Text } = p.el;
  const c = p.chat;
  if (!c) return <Text dimColor>Reading this chat…</Text>;
  const shade = (i: number) => SHADES[i % SHADES.length];
  const cells = c.context.map((x) =>
    c.max ? Math.max(1, Math.round((x.tokens / c.max) * BAR)) : 0,
  );
  const rest = Math.max(0, BAR - cells.reduce((a, b) => a + b, 0));
  const facts = [
    `${c.turns} turn${c.turns === 1 ? "" : "s"}`,
    duration(c.minutes),
    c.usd === undefined ? null : `$${c.usd.toFixed(2)}`,
    c.compactions
      ? `${c.compactions} compaction${c.compactions === 1 ? "" : "s"}`
      : null,
  ].filter(Boolean);
  return (
    <Box flexDirection="column" gap={1}>
      <Box justifyContent="space-between" gap={2} flexWrap="wrap">
        <Text>
          <Text bold>{c.model.replace(/^claude-/, "")}</Text>
          <Text
            dimColor
          >{` · ${c.effort ?? "auto"}${c.locked ? " ▪" : ""}`}</Text>
        </Text>
        <Text dimColor>{facts.join(" · ")}</Text>
      </Box>
      {c.max ? (
        <Box flexDirection="column">
          <Text>
            {cells.map((n, i) => (
              <Text key={`bar-${i}`} color={shade(i)}>
                {"█".repeat(n)}
              </Text>
            ))}
            <Text dimColor>{"░".repeat(rest)}</Text>
            <Text dimColor>{`  ${k(c.used)} / ${k(c.max)}`}</Text>
          </Text>
          {c.context.map((x, i) => (
            <Text key={`cat-${x.name}`}>
              <Text color={shade(i)}>{"■ "}</Text>
              <Text>{x.name.padEnd(22)}</Text>
              <Text dimColor>{k(x.tokens)}</Text>
            </Text>
          ))}
        </Box>
      ) : null}
      <Box flexDirection="column">
        <Text dimColor>{`Files this chat changed (${c.files.length})`}</Text>
        {c.files.length ? (
          c.files
            .slice(-15)
            .map((f) => (
              <Text key={`file-${f}`} wrap="truncate-start">{`  ${f}`}</Text>
            ))
        ) : (
          <Text dimColor> none yet</Text>
        )}
      </Box>
      {c.agents.length ? (
        <Text>
          <Text dimColor>Subagents </Text>
          {c.agents.map((a) => `${a.type} ×${a.n}`).join(" · ")}
        </Text>
      ) : null}
    </Box>
  );
}

// The Messages tab: this chat's latest messages, each with Remember, which asks the model to
// keep it as a project lesson in AGENTS.md (kit:lessons: only what qualifies, nothing else).
export function messagesTab(p: Parts) {
  const { Box, Text, Button } = p.el;
  const recent = p.messages;
  if (!recent) return <Text dimColor>Reading this chat…</Text>;
  return (
    <Box flexDirection="column" gap={1}>
      <Text dimColor wrap="wrap">
        Pick a message to keep as a project lesson. Remember hands it to
        /kit:lessons, which writes it to AGENTS.md only when a later session
        could not learn it from the code.
      </Text>
      {recent.length ? (
        recent.map((m, i) => (
          <Box key={`mem-${i}`} justifyContent="space-between" gap={2}>
            <Text wrap="truncate-end">
              <Text dimColor>{m.role === "you" ? "you     " : "claude  "}</Text>
              {m.text}
            </Text>
            <Button
              key={`remember-${i}`}
              label="Remember"
              dimColor
              onPress={() => p.act.remember(m.text)}
            />
          </Box>
        ))
      ) : (
        <Text dimColor>Nothing said in this chat yet.</Text>
      )}
    </Box>
  );
}

